-- SQLite SQL - import raw CSV tables first.
SELECT COUNT(*) AS accounts, SUM(CASE WHEN status IN ('active','past_due') THEN mrr ELSE 0 END) AS mrr, 12*SUM(CASE WHEN status IN ('active','past_due') THEN mrr ELSE 0 END) AS arr, 100.0*AVG(CASE WHEN status='churned' THEN 1.0 ELSE 0 END) AS historical_churn_pct FROM subscriptions;
SELECT a.plan, COUNT(*) AS accounts, SUM(CASE WHEN s.status IN ('active','past_due') THEN s.mrr ELSE 0 END) AS mrr, 100.0*AVG(CASE WHEN s.status='churned' THEN 1.0 ELSE 0 END) AS churn_pct FROM accounts a JOIN subscriptions s USING(account_id) GROUP BY a.plan ORDER BY mrr DESC;
SELECT a.country, COUNT(*) AS accounts, SUM(CASE WHEN s.status IN ('active','past_due') THEN s.mrr ELSE 0 END) AS mrr FROM accounts a JOIN subscriptions s USING(account_id) GROUP BY a.country ORDER BY mrr DESC;
SELECT SUM(amount) AS billings, SUM(CASE WHEN status='paid' THEN amount ELSE 0 END) AS paid, 100.0*SUM(CASE WHEN status='paid' THEN amount ELSE 0 END)/SUM(amount) AS collection_pct, SUM(CASE WHEN status='open' THEN amount ELSE 0 END) AS open_amount FROM invoices WHERE status<>'void';
SELECT substr(invoice_date,1,7) AS month, SUM(amount) AS billings FROM invoices WHERE status<>'void' GROUP BY 1 ORDER BY 1;
WITH jan AS (SELECT account_id,SUM(amount) AS amount FROM invoices WHERE substr(invoice_date,1,7)='2025-01' AND status<>'void' GROUP BY account_id), dec AS (SELECT account_id,SUM(amount) AS amount FROM invoices WHERE substr(invoice_date,1,7)='2025-12' AND status<>'void' GROUP BY account_id) SELECT a.plan, SUM(jan.amount) AS jan, SUM(COALESCE(dec.amount,0)) AS dec, 100.0*SUM(COALESCE(dec.amount,0))/SUM(jan.amount) AS retention_pct FROM jan JOIN accounts a USING(account_id) LEFT JOIN dec USING(account_id) GROUP BY a.plan;
SELECT s.status, COUNT(*) AS tickets, AVG(t.satisfaction_score) AS csat, COUNT(t.satisfaction_score) AS ratings, AVG(t.resolution_hours) AS resolution_hours FROM support_tickets t JOIN subscriptions s USING(account_id) GROUP BY s.status;
WITH billed AS (SELECT account_id,SUM(amount) AS billings FROM invoices WHERE status<>'void' GROUP BY account_id HAVING SUM(amount)>0), ranked AS (SELECT *,ROW_NUMBER() OVER(ORDER BY billings DESC,account_id) AS rn,COUNT(*) OVER() AS n FROM billed) SELECT 100.0*SUM(CASE WHEN rn <= (n+4)/5 THEN billings ELSE 0 END)/SUM(billings) AS top_20_share FROM ranked;
